package com.klef.soa.faculty.service;
import java.io.*;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;
import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
import com.google.zxing.*;import com.google.zxing.client.j2se.MatrixToImageWriter;import com.google.zxing.common.BitMatrix;import com.warrenstrange.googleauth.*;
import com.klef.soa.faculty.dto.*;import com.klef.soa.faculty.entity.*;import com.klef.soa.faculty.repository.*;import com.klef.soa.faculty.security.MfaCipher;
@Service public class FacultyMfaService {
 private static final int TTL=300,MAX=5;private final FacultyRepository faculties;private final MfaChallengeRepository challenges;private final PasswordEncoder encoder;private final MfaCipher cipher;private final GoogleAuthenticator totp=new GoogleAuthenticator();
 public FacultyMfaService(FacultyRepository f,MfaChallengeRepository c,PasswordEncoder e,MfaCipher x){faculties=f;challenges=c;encoder=e;cipher=x;}
 @Transactional public MfaChallengeResponse login(FacultyLoginRequest request){Faculty f=faculties.findByEmailIgnoreCase(request.email().trim()).orElseThrow(()->unauthorized());if(!encoder.matches(request.password(),f.getPasswordHash()))throw unauthorized();if(!"ACTIVE".equalsIgnoreCase(f.getStatus()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Faculty account is inactive. Contact an administrator.");challenges.deleteExpired(Instant.now());String id=UUID.randomUUID().toString();challenges.save(new MfaChallenge(id,f.getId(),Instant.now().plusSeconds(TTL)));return new MfaChallengeResponse(true,!f.isMfaEnabled(),id);}
 @Transactional public MfaSetupResponse setup(String id){MfaChallenge c=challenge(id);Faculty f=findActive(c.getFacultyId());if(f.isMfaEnabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"Faculty MFA already enabled");if(c.getPendingSecret()==null)c.setPendingSecret(cipher.encrypt(totp.createCredentials().getKey()));String label=URLEncoder.encode("EduPulse Academy:"+f.getEmail(),StandardCharsets.UTF_8),issuer=URLEncoder.encode("EduPulse Academy",StandardCharsets.UTF_8);String uri="otpauth://totp/"+label+"?secret="+cipher.decrypt(c.getPendingSecret())+"&issuer="+issuer+"&algorithm=SHA1&digits=6&period=30";try{BitMatrix matrix=new MultiFormatWriter().encode(uri,BarcodeFormat.QR_CODE,300,300);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matrix,"PNG",out);return new MfaSetupResponse("data:image/png;base64,"+Base64.getEncoder().encodeToString(out.toByteArray()),TTL);}catch(Exception e){throw new IllegalStateException("Could not create MFA QR",e);}}
 @Transactional public FacultyVerifyResponse verify(CodeRequest request){MfaChallenge c=challenges.lock(request.challengeId()).orElseThrow(()->unauthorized());if(!c.getExpiresAt().isAfter(Instant.now())){challenges.delete(c);return new FacultyVerifyResponse("EXPIRED",null);}if(c.getFailedAttempts()>=MAX){challenges.delete(c);return new FacultyVerifyResponse("RATE_LIMITED",null);}Faculty f=faculties.findById(c.getFacultyId()).orElse(null);if(f==null||!"ACTIVE".equalsIgnoreCase(f.getStatus())){challenges.delete(c);return new FacultyVerifyResponse("REJECTED",null);}String encrypted=c.getPendingSecret()!=null?c.getPendingSecret():f.getMfaSecretEncrypted();boolean valid=false;if(encrypted!=null)try{valid=totp.authorize(cipher.decrypt(encrypted),Integer.parseInt(request.code()));}catch(RuntimeException ignored){}if(!valid){c.setFailedAttempts(c.getFailedAttempts()+1);if(c.getFailedAttempts()>=MAX){challenges.delete(c);return new FacultyVerifyResponse("RATE_LIMITED",null);}return new FacultyVerifyResponse("INVALID",null);}if(c.getPendingSecret()!=null){f.setMfaSecretEncrypted(c.getPendingSecret());f.setMfaEnabled(true);faculties.save(f);}challenges.delete(c);return new FacultyVerifyResponse("SUCCESS",f.getEmail());}
 private MfaChallenge challenge(String id){MfaChallenge c=challenges.lock(id).orElseThrow(()->unauthorized());if(!c.getExpiresAt().isAfter(Instant.now())){challenges.delete(c);throw unauthorized();}return c;}
 private Faculty findActive(Long id){Faculty f=faculties.findById(id).orElseThrow(()->unauthorized());if(!"ACTIVE".equalsIgnoreCase(f.getStatus()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Faculty account is inactive");return f;}
 private ResponseStatusException unauthorized(){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email/password or MFA challenge");}
}
